1	import { NextResponse } from "next/server";
2	import { checkRateLimit } from "@/lib/rate-limit";
3	import { trustedClientIp } from "@/app/api/_lib/client-ip";
4	import { currentUser } from "@/lib/auth";
5	import { insertDeployFunnelEvent } from "@/lib/deploy-funnel";
6	
7	export const runtime = "nodejs";
8	
9	/**
10	 * Deploy-funnel event sink. Called fire-and-forget by the customer deploy wizards
11	 * (components/customer/*DeployWizard.tsx) as a person moves through the steps, and
12	 * by the same wizards when a step throws / a provision call fails. Server-side
13	 * provisioning failures are recorded via `recordDeployFunnelError` (lib/deploy-funnel.ts)
14	 * rather than this HTTP path.
15	 *
16	 * Records one `DeployFunnelEvent`. Like /api/track it MUST NOT throw or block —
17	 * analytics is strictly best-effort. It attributes the signed-in account via
18	 * `currentUser()` (the auth cookie rides the POST) and the stable visitor cookie,
19	 * so an admin can later tie a stuck/errored session back to a real customer.
20	 */
21	
22	const VID_COOKIE = "nx_vid";
23	const PRODUCTS = new Set(["vps", "game", "hosting", "email"]);
24	const TYPES = new Set(["step", "error", "complete"]);
25	
26	function readCookie(req: Request, name: string): string | null {
27	  const raw = req.headers.get("cookie");
28	  if (!raw) return null;
29	  for (const part of raw.split("; ")) {
30	    if (part.startsWith(`${name}=`)) return part.slice(name.length + 1);
31	  }
32	  return null;
33	}
34	
35	function cleanId(v: unknown): string | null {
36	  if (typeof v !== "string") return null;
37	  const s = v.trim();
38	  if (!s || s.length > 64 || !/^[A-Za-z0-9._-]+$/.test(s)) return null;
39	  return s;
40	}
41	
42	function cleanStr(v: unknown, max: number): string | null {
43	  if (typeof v !== "string") return null;
44	  const s = v.trim().slice(0, max);
45	  return s || null;
46	}
47	
48	export async function POST(req: Request) {
49	  try {
50	    const ip = trustedClientIp(req);
51	    const rl = checkRateLimit(`deploystep:${ip}`, { max: 120, windowMs: 60_000 });
52	    if (!rl.ok) return new NextResponse(null, { status: 204 });
53	
54	    const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
55	
56	    const product = typeof body.product === "string" ? body.product : "";
57	    if (!PRODUCTS.has(product)) return NextResponse.json({ ok: true });
58	    const step = cleanStr(body.step, 60);
59	    if (!step) return NextResponse.json({ ok: true });
60	    const stepIndexRaw = typeof body.stepIndex === "number" ? body.stepIndex : Number(body.stepIndex);
61	    const stepIndex = Number.isFinite(stepIndexRaw) ? Math.max(0, Math.min(50, Math.round(stepIndexRaw))) : 0;
62	    const type = typeof body.type === "string" && TYPES.has(body.type) ? body.type : "step";
63	
64	    let userId: string | null = null;
65	    try {
66	      userId = (await currentUser())?.id ?? null;
67	    } catch {
68	      /* best-effort */
69	    }
70	    const vid = readCookie(req, VID_COOKIE);
71	    const visitorId = vid && /^[A-Za-z0-9-]{8,64}$/.test(vid) ? vid : null;
72	
73	    await insertDeployFunnelEvent({
74	      userId,
75	      visitorId,
76	      sessionId: cleanId(body.sessionId),
77	      product,
78	      step,
79	      stepIndex,
80	      type,
81	      errorCode: type === "error" ? cleanStr(body.errorCode, 60) : null,
82	      errorMessage: type === "error" ? cleanStr(body.errorMessage, 300) : null,
83	    });
84	  } catch {
85	    /* never surface capture failures */
86	  }
87	  return NextResponse.json({ ok: true });
88	}
