1	// Client-side deploy-funnel beacons. Dependency-free (no server imports) so it is
2	// safe to pull into the customer wizard client components. Fires fire-and-forget
3	// POSTs to /api/track/deploy-step; never throws, never blocks the wizard.
4	
5	export type DeployProduct = "vps" | "game" | "hosting" | "email";
6	
7	/** Read the per-tab session id the VisitTracker maintains, so a funnel event can
8	 *  be tied to the same session as the pageviews. */
9	function sessionId(): string | null {
10	  try {
11	    return window.sessionStorage.getItem("nx_sid");
12	  } catch {
13	    return null;
14	  }
15	}
16	
17	function send(payload: Record<string, unknown>): void {
18	  try {
19	    const body = JSON.stringify({ ...payload, sessionId: sessionId() });
20	    if (typeof navigator !== "undefined" && navigator.sendBeacon) {
21	      navigator.sendBeacon("/api/track/deploy-step", new Blob([body], { type: "application/json" }));
22	    } else {
23	      fetch("/api/track/deploy-step", {
24	        method: "POST",
25	        headers: { "content-type": "application/json" },
26	        body,
27	        keepalive: true,
28	      }).catch(() => {});
29	    }
30	  } catch {
31	    /* best-effort */
32	  }
33	}
34	
35	/**
36	 * Record that the user REACHED a wizard step. De-duped per tab-session so a
37	 * component re-render / strict-mode double-mount doesn't count a step twice — the
38	 * funnel measures distinct sessions reaching each step.
39	 */
40	export function trackDeployStep(product: DeployProduct, step: string, stepIndex: number): void {
41	  if (typeof window === "undefined") return;
42	  const key = `nx_dfstep:${product}:${stepIndex}:${step}`;
43	  try {
44	    if (window.sessionStorage.getItem(key)) return;
45	    window.sessionStorage.setItem(key, "1");
46	  } catch {
47	    /* storage disabled — still emit, just without cross-render dedupe */
48	  }
49	  send({ product, step, stepIndex, type: "step" });
50	}
51	
52	/**
53	 * Record that a wizard step FAILED (a validation error, or an API/provision call
54	 * that returned/raised an error). NOT de-duped — every real failure is a signal.
55	 */
56	export function trackDeployError(
57	  product: DeployProduct,
58	  step: string,
59	  stepIndex: number,
60	  errorCode: string,
61	  errorMessage?: string,
62	): void {
63	  if (typeof window === "undefined") return;
64	  send({ product, step, stepIndex, type: "error", errorCode, errorMessage: errorMessage ?? null });
65	}
66	
67	/** Record that the deploy SUCCEEDED (bottom of the funnel). De-duped per session. */
68	export function trackDeployComplete(product: DeployProduct, step: string, stepIndex: number): void {
69	  if (typeof window === "undefined") return;
70	  const key = `nx_dfdone:${product}`;
71	  try {
72	    if (window.sessionStorage.getItem(key)) return;
73	    window.sessionStorage.setItem(key, "1");
74	  } catch {
75	    /* ignore */
76	  }
77	  send({ product, step, stepIndex, type: "complete" });
78	}
