203	    const userOf = new Map<string, string>();
204	
205	    // Per-step aggregation.
206	    type Acc = {
207	      order: number;
208	      reached: Set<string>;
209	      errored: Set<string>;
210	      errorEvents: number;
211	      errors: Map<string, { code: string | null; message: string | null; count: number }>;
